def rep_between(a, b, new):
    """replace s[index(a) : index(b)] (a kept out of nothing: the block from a up to, not including, b) - both anchors unique"""
    global s
    assert s.count(a) == 1 and s.count(b) == 1, (s.count(a), s.count(b), a[:80], b[:80])
    i, j = s.index(a), s.index(b)
    assert i < j
    OLDS.append(s[i:j])
    s = s[:i] + new + s[j:]


