M(tree, r"""
public static String buy(String k, java.util.UUID u, int idx, int expect, boolean allowed) {
  if (!allowed) return "-Rebirth is switched off on this server.";
  if (idx < 0 || idx >= NID.length) return "-Pick a node first.";
  String g = gate(k);
  if (g != null) return g;
  java.util.Properties cur = @PKG@.RbStore.readNow(k);
  if (cur == null) return "-Your rebirth file cannot be read - nothing changed (server log).";
  int a = NARM[idx];
  String arm = @PKG@.RbMath.ARMS[a];
  int l = lv(cur, idx);
  if (l != expect) return "-" + NNAME[idx] + " changed meanwhile (now level " + l + ") - look again.";
  if (l >= NMAX[idx]) return "-" + NNAME[idx] + " is already at its max level.";
  int r = NROW[idx];
  if (r >= openRows(cur, a)) return "-Row " + (r + 1) + " of the " + arm + " arm is still locked.";
  long c = cost(armLevels(cur, a));
  long have = big(cur, "pts." + arm);
  if (have < c) return "-Not enough " + arm + " points: this level costs " + c + ", you have " + have + ".";
  java.util.Properties p = new java.util.Properties();
  p.putAll(cur);
  p.setProperty("pts." + arm, String.valueOf(have - c));
  p.setProperty("spent." + arm, String.valueOf(big(cur, "spent." + arm) + c));
  p.setProperty("node." + NID[idx], String.valueOf(l + 1));
  if (NTITLE[idx].length() > 0) p.setProperty("title", NTITLE[idx]);
  String e = @PKG@.RbStore.save(k, p);
  if (e != null) return "-Could not save - nothing changed: " + e;
  BUYS.incrementAndGet();
  @PKG@.RbCfg.info("tree: " + k + " bought " + NID[idx] + " level " + (l + 1) + " for " + c + " " + arm + " points (" + (have - c) + " left)");
  if (u != null) { try { @PKG@.RbPub.publish(u); } catch (Throwable t) { } }
  return "+" + NNAME[idx] + " level " + (l + 1) + " bought - " + c + " " + arm + (c == 1L ? " point" : " points") + " spent.";
}""")
