M(page, r"""
public void fillTree(String k) {
  java.util.Properties p = @PKG@.RbStore.get(k);
  int N = @PKG@.RbTree.NID.length;
  this.nc = new String[N];
  this.nt = new String[N];
  this.ntc = new String[N];
  this.pt = new String[8];
  int[] open = new int[8];
  for (int a = 0; a < 8; a++) {
    open[a] = @PKG@.RbTree.openRows(p, a);
    String arm = @PKG@.RbMath.ARMS[a];
    this.pt[a] = arm + "  " + @PKG@.RbTree.shortN(@PKG@.RbTree.big(p, "pts." + arm)) + " pts  " + @PKG@.RbTree.armLevels(p, a) + "/" + @PKG@.RbTree.armMax(a);
  }
  for (int i = 0; i < N; i++) {
    int a = @PKG@.RbTree.NARM[i];
    int r = @PKG@.RbTree.NROW[i];
    int l = @PKG@.RbTree.lv(p, i);
    if (r < open[a]) {
      this.nt[i] = String.valueOf(l);
      if (l >= @PKG@.RbTree.NMAX[i]) { this.nc[i] = COL_MAX[a]; this.ntc[i] = "@WHITE@"; }
      else if (l > 0) { this.nc[i] = COL_PART[a]; this.ntc[i] = "@WHITE@"; }
      else { this.nc[i] = "@NOPEN@"; this.ntc[i] = "@MUTED@"; }
    } else if (r == open[a]) {
      this.nc[i] = "@NNEXT@";
      this.nt[i] = @PKG@.RbTree.rowLevels(p, a, r - 1) + "/" + @PKG@.RbTree.need(a, r - 1);
      this.ntc[i] = "@NNEXTTX@";
    } else {
      this.nc[i] = "@NLOCK@";
      this.nt[i] = "";
      this.ntc[i] = "@NLOCKTX@";
    }
    if (i == this.sel) { this.nc[i] = "@NSEL@"; this.ntc[i] = "@NLOCK@"; }
  }
  if (this.view == 1 && this.sel >= 0 && this.sel < N) fillNode(k, p);
  else this.view = 0;
}""".replace("@WHITE@", WHITE).replace("@NOPEN@", N_OPEN).replace("@MUTED@", MUTED).replace("@NNEXTTX@", N_NEXT_TX).replace("@NNEXT@", N_NEXT)
   .replace("@NLOCKTX@", N_LOCK_TX).replace("@NLOCK@", NODE_LOCKED).replace("@NSEL@", N_SEL))
