M(page, r"""
public static String act(String data) {
  if (data == null) return null;
  int i = data.indexOf("\"a\"");
  if (i < 0) return null;
  int c = data.indexOf(':', i + 3);
  if (c < 0) return null;
  int q1 = data.indexOf('"', c + 1);
  if (q1 < 0) return null;
  int q2 = data.indexOf('"', q1 + 1);
  if (q2 < 0) return null;
  return data.substring(q1 + 1, q2);
}""")
