M(page, r"""
public void buy(@REF@ ref, @ST@ st) {
  if (this.sel < 0 || this.pending || this.buyKey == null || this.buySel != this.sel) return;
  String k = this.buyKey;
  int l = this.buyLevel;
  if (!k.equals(@PKG@.RbCfg.pkey(this.me))) {
    this.status = "-Your active profile changed - look at the node again.";
    if (!this.testMode) rebuild();
    return;
  }
  this.lastRef = ref;
  this.lastStore = st;
  this.pending = true;
  this.status = null;
  boolean al = @PKG@.RbCfg.ON || @PKG@.RbCfg.isAdmin(this.me);
  String r = @PKG@.RbJob.submit(new @PKG@.RbJob(1, k, this.me, this.sel, l, al, this));
  if (r == null) return;   // queued: RbJob.run sets the result and refreshes this page on the world thread
  jobDone(r);
  if (!this.testMode) rebuild();
}""")
