M(page, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  String a = act(data);
  if (a == null) return;
  if (a.equals("nexus")) {   // fix round: the Nexus = the button the left panel offers (from the node view: back to the rebirth view first)
    if (this.view != 0) this.armedAt = 0L;   // fix round 2: from the node view the armed note was not on screen - this click only arms
    this.view = 0;
    this.sel = -1;
    this.status = null;
    if (this.goKind != 1 && this.goKind != 2) { this.last = "=nothing"; if (!this.testMode) rebuild(); return; }
    a = this.goKind == 2 ? "rbcont" : "rbgo";
  }
  if (a.equals("rbgo") || a.equals("rbcont")) {
    String r = click(System.currentTimeMillis(), this.testMode ? this.world : worldOf(st), a.equals("rbcont"));
    this.last = r;
    if (this.testMode) return;
    if (r.startsWith("+")) { this.gone = true; close(); @PKG@.RbTx.tell(String.valueOf(this.me), "[Rebirth] " + r.substring(1), "#E8A93B"); return; }
    if (r.startsWith("-")) @PKG@.RbTx.tell(String.valueOf(this.me), "[Rebirth] " + r.substring(1), "#ff6b6b");
    rebuild();
    return;
  }
  if (a.length() > 1 && a.charAt(0) == 'n') {   // a tree node: select it, show it on the left
    int i = -1;
    try { i = Integer.parseInt(a.substring(1)); } catch (Throwable t) { i = -1; }
    if (i >= 0 && i < @PKG@.RbTree.NID.length) { this.sel = i; this.view = 1; this.status = null; this.armedAt = 0L; }   // fix round 2: leaving the rebirth view disarms
    if (!this.testMode) rebuild();
    return;
  }
  if (a.equals("back")) { this.view = 0; this.sel = -1; this.status = null; this.armedAt = 0L; if (!this.testMode) rebuild(); return; }
  if (a.equals("buy")) { buy(ref, st); return; }
  if (this.testMode) return;
  if (a.equals("close")) { this.gone = true; close(); }
}""")
