assert s.index("public static String buy(String k") > s.index('pub = mk("RbPub")') and s.index("public static String buy(String k") < s.index('chk = mk("RbCheck")')
assert s.index("public static Object[] market(String k)") < s.index("public static Object[] reqs(")
